// READ parsed OCR data from "Code in JavaScript" node
const parsedOCR = $node["Code in JavaScript"].json;

// READ WEBHOOK BODY data
const webhook = $node["Webhook"].json.body;

const name = (webhook.name || "").toLowerCase();
const reviewFromWebhook = (webhook.review_content || "").toLowerCase();

// The extracted review from OCR
const extractedName = (parsedOCR.name || "").toLowerCase();
const extractedReview = (parsedOCR.review || "").toLowerCase();

// Name match: check if names match
const nameMatch = extractedName.includes(name) || name.includes(extractedName);

// Fuzzy match review content (only keywords ≥5 chars)
const keyWords = reviewFromWebhook.split(/\s+/).filter(w => w.length >= 5);

let hits = 0;
for (const w of keyWords) {
  if (extractedReview.includes(w)) hits++;
}

// Require at least 25% word match (tunable)
const contentMatch = hits >= Math.ceil(keyWords.length * 0.25);

// Final verdict
const verified = nameMatch && contentMatch;

return [
  {
    json: {
      name,
      review: reviewFromWebhook,
      extracted_name: parsedOCR.name,
      extracted_review: parsedOCR.review,
      nameMatch,
      contentMatch,
      keyWords,
      hits,
      verified
    }
  }
];

// Get the OCR text from the Analyze image node output
const analyzeOutput = $input.item.json;

// The structure is json[0].content[0].text
const rawText = analyzeOutput[0]?.content?.[0]?.text || "";

// Stop workflow if empty
if (!rawText || rawText.trim() === "") {
  throw new Error("OCR text was empty or model refused.");
}

// Extract JSON block inside ```json ... ```
let cleaned = rawText.match(/```json([\s\S]*?)```/i);
if (cleaned) {
  cleaned = cleaned[1].trim();
} else {
  // If no JSON code block found, try to use the raw text
  cleaned = rawText.trim();
}

// Parse the JSON text into an object
let obj;
try {
  obj = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Failed to parse OCR JSON: " + e.message + "\nRaw:\n" + cleaned);
}

// Return the parsed data
return [
  {
    json: obj
  }
];
